public interface Vehicle {
    default void start() {
        System.out.println("Starting generic vehicle...");
    }
}

public interface Alarm {
    default void start() {
        System.out.println("Sounding security alarm!");
    }
}

public class SmartCar implements Vehicle, Alarm {
    @Override
    public void start() {
        // Explicitly resolving the diamond/conflict problem
        Vehicle.super.start();
        Alarm.super.start();
        System.out.println("SmartCar systems fully online.");
    }
}
